                  ("v27", "「彼何意念？善實！相具足，如來無上正遍知證覺"),
                  ("v28", "「若復，善實！善家子，若善家女，若恒伽河沙等世界七寶"),
                  ("v29", "「雖然復次時，善實！若有如是語：『如來去"),
                  ("v30", "「若復，善實！善家子，若善家女，若所有三千大千世界地塵"),
                  ("v31", "彼何所因？若此有，善實！如是說：『我見"),
