# 藏譯 TMX 無品標記，品界由 84000 英譯 TEI 定位（tripitaka_compare_auto.tei_chapter_starts）。
def _vkn_versions(sa_ch: int, bo_rng: tuple[int, int], heads: dict[str, list[str]],
                  cuts: dict[str, list], bo_lines: list, ends: dict[str, str] | None = None) -> list[dict]:
    """ends：某本的品界與梵本不同時，在該品裡截止於這幾個字之前（支謙〈諸法言品〉尾段屬梵本第 5 品）。"""
    vs = [
        {"id": "sa", "lang": "sa", "label": "梵本", "who": "大正大學校訂本（2006）・GRETIL",
         "src": {"orig": "T0475", "lang": "sa", "ref": f"Vimalakīrtinirdeśa {sa_ch}"}, "cuts": cuts["sa"]},
        {"id": "T0474", "lang": "lzh", "label": "支謙本", "who": "支謙譯《維摩詰經》・約 223–253 年",
         "src": {"work": "T0474", "nodes": heads["T0474"], "start": cuts["T0474"][0][1]}, "cuts": cuts["T0474"]},
        {"id": "T0475", "lang": "lzh", "label": "羅什本", "who": "鳩摩羅什譯《維摩詰所說經》・406 年",
         "src": {"work": "T0475", "nodes": heads["T0475"], "start": cuts["T0475"][0][1]}, "cuts": cuts["T0475"]},
        {"id": "T0476", "lang": "lzh", "label": "玄奘本", "who": "玄奘譯《說無垢稱經》・650 年",
         "src": {"work": "T0476", "nodes": heads["T0476"], "start": cuts["T0476"][0][1]}, "cuts": cuts["T0476"]},
        {"id": "bo", "lang": "bo", "label": "藏譯", "who": "法性戒譯・德格版 Toh 176・84000",
         "src": {"tmx": "toh176", "side": "bo", "from": bo_rng[0], "to": bo_rng[1]}, "lines": bo_lines},
        {"id": "en", "lang": "en", "label": "84000 英譯", "who": "譯自藏譯・與藏文逐句對齊",
         "src": {"tmx": "toh176", "side": "en", "from": bo_rng[0], "to": bo_rng[1]}, "lines": bo_lines},
    ]
    for v in vs:
        if v["id"] in (ends or {}):
            v["src"]["end"] = ends[v["id"]]
    return vs


