# 第 4 品：窮子喻按梵本段落細切（第 4、6 段各在情節轉折處再切一刀）；正法華散文改寫幅度大
# （窮子調車馬而非除糞、無「名之為兒」與「領知眾物」兩節），對不上的節從缺。迦葉偈（梵 4.1–62）分四組。
