# 第二段（科 10–34）：成佛以後到菩薩功德，終於佛令阿難西向禮拜之前。這一段各本次第差最多：
# 平等覺經、大阿彌陀經把阿闍世王太子、講堂說法、阿逸菩薩問答插在中間，又有三毒五惡段，
# 須彌山之問在三輩之前；梵本與法賢本菩提樹在十方菩薩禮覲偈之後。科目照菩提流志本排，
# 各本照原本次第下刀（reorder），同一主題重出時只在主要那次下刀，重出段落隨前一節。
# 菩提流志本第 21 科「人如六天」與第 20 科合為一節（康僧鎧本乞人喻夾在兩段受用之間，分開會重出）。
