                   ("sv-11", "佛告阿難：「無量壽佛威神光明最尊第一"), ("sv-13", "佛語阿難：「無量壽佛壽命長久"),
                   ("sv-12", "又聲聞、菩薩其數難量"), ("sv-15", "「又其國土，七寶諸樹"), ("sv-16", "「又無量壽佛其道場樹"),
                   ("sv-18", "佛告阿難：「世間帝王有百千音樂"), ("sv-19", "無有三塗苦難之名"),
                   ("sv-20", "「阿難！彼佛國土諸往生者"), ("sv-22", "自然德風徐起微動"), ("sv-23", "「又眾寶蓮華周滿世界"),
                   ("sv-25", "佛告阿難：「其有眾生生彼國者，皆悉住於正定之聚"), ("sv-26", "十方恒沙諸佛如來皆共讚歎"),
                   ("sv-27", "佛告阿難：「十方世界諸天人民，其有至心願生彼國，凡有三輩"),
